ee:message.ee:set-payload:
%dw 2.0
output application/json
var header = payload.availabilityRequest.header
var detail = payload.availabilityRequest.detail
---
{
	peticionConsultaDisponibilidad: {
		encabezadoMensaje: {
			idDisponibilidad: header.availabilityId,
			numeroOrdenAprovisionador: header.provisioningOrderNumber,
			numeroRevision: header.revisionNumber,
			tecnologiaETB: header.technology,
			fechaPeticionOrden: header.requestDate
		},
		detalleMensaje: {
			modoConsulta: detail.queryMode,
			tipoDisponibilidad: detail.availabilityType,
			orderItems: detail.orderItem map (item) -> {
				idProductoTecnico: item.technicalProductId,
				idServicio: item.serviceId,
				idServicioPadre: item.parentServiceId,
				idServicioRaiz: item.rootServiceId,
				accion: item.action,
				usoServicio: item.serviceUsage,
				idProductoTecnicoPadre: item.parentTechnicalProductId,
				idProductoTecnicoRaiz: item.rootTechnicalProductId,
				cuentaServicio: {
					idCuentaServicio: item.serviceAccount.id,
					direccionServicio: item.serviceAccount.place map (place) -> {
						codigoUnicoDireccion: place.id,
						codigoDepartamento: place.stateOrProvince,
						codigoMunicipio: place.cityCode,
						codigoPais: place.country,
						direccionNormalizada: place.formattedAddress,
						latitud: place.geographicLocation.latitude,
						longitud: place.geographicLocation.longitude,
						tecnologias: place.technology map (tech) -> {
							nombreTecnologia: tech.name,
							prioridadTecnologia: tech.priority,
							zona: tech.zone,
							cobertura: {
								tipoCobertura: tech.coverage.'type',
								nombreCobertura: tech.coverage.name
							}
						}
					}
				},
				atributos: item.characteristic map (att) -> {
					atributo: att.name,
					valor: att.value,
					accion: att.action
				}
			}
		}
	}
}

%dw 2.0
output application/json
var src = payload.respuestaConsultaDisponibilidad
var header = src.encabezadoMensaje
var detail = src.detalleMensaje
---
{
	status: if ( (detail.resultado.resultado) == "OK" ) 200 
    else 400,
	code: detail.resultado.resultado,
	message: {
		message: if ( (detail.resultado.resultado) == "OK" ) "Successful Transaction." 
      else 
        (detail.resultado.descripcionErrorResultado default "Error")
	},
	availabilityResponse: {
		header: {
			availabilityId: header.idDisponibilidad,
			provisioningOrderNumber: header.numeroOrdenAprovisionador,
			revisionNumber: header.numeroRevision,
			technology: header.tecnologiaETB,
			requestDate: header.fechaPeticionOrden
		},
		detail: {
			overall: {
				qualificationResult: if ( (detail.global.disponibilidad default "") == "FACTIBLE" ) "FEASIBLE" 
          else 
            detail.global.disponibilidad,
				reason: {
					parentServiceId: detail.global.motivo.idServicioPadre,
					resource: detail.global.motivo.recurso,
					description: detail.global.motivo.descripcion
				}
			},
			orderItem: (detail.orderItems default []) map (item) -> {
				serviceId: item.idServicio default null
			},
			result: {
				status: detail.resultado.resultado,
				errorCode: detail.resultado.codigoErrorResultado,
				errorMessage: detail.resultado.descripcionErrorResultado
			}
		}
	}
}
